<script setup lang="ts">
import {computed,onUnmounted,ref} from 'vue'
type Job={id:string,due_at:number,payload:{quantity:number},status:string,attempts:number}
type Status={identity:{username:string,role:string,scopes:string[]},providers:Record<string,string>,quantum:number,simulation_time:string,run:{id:string,epoch:string,mode:string,state:string,granted:number,requested:number,committed:number,speed:number,error:string|null,scenario:{seed:number,time_zone:string}},effects:number,jobs:Job[],heartbeats:{role:string,healthy:boolean,detail:string}[],pending_boundary_outputs:number}
const username=ref(''),password=ref(''),status=ref<Status|null>(null),error=ref(''),busy=ref(false),due=ref(1),quantity=ref(1),confirmation=ref(''),audit=ref<{id:string,actor:string,action:string,outcome:string,status_code:number}[]>([])
const operator=computed(()=>status.value?.identity.scopes.includes('runs:control'))
const canSchedule=computed(()=>status.value?.identity.scopes.includes('jobs:write'))
let timer:ReturnType<typeof setInterval>|undefined;let key=crypto.randomUUID();let credentials='';let refreshing=false
async function api(path:string,body?:unknown,idempotency?:string){const response=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',headers:{Authorization:'Basic '+credentials,'Content-Type':'application/json',...(idempotency?{'Idempotency-Key':idempotency}:{})},...(body===undefined?{}:{body:JSON.stringify(body)})});const data=await response.json();if(!response.ok)throw new Error(data.detail||`Request failed (${response.status})`);return data}
async function refresh(){if(refreshing)return;refreshing=true;try{status.value=await api('status');error.value=''}catch(e){error.value=(e as Error).message}finally{refreshing=false}}
async function login(){busy.value=true;try{credentials=btoa(String.fromCharCode(...new TextEncoder().encode(username.value+':'+password.value)));status.value=await api('status');error.value='';due.value=Math.max(status.value!.run.granted,status.value!.run.requested)+status.value!.quantum;timer=setInterval(refresh,2000)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function newKey(){key=crypto.randomUUID()}
function logout(){if(timer)clearInterval(timer);credentials='';password.value='';status.value=null;audit.value=[]}
async function command(action:string,body:unknown={}){busy.value=true;try{await api('control/'+action,body);await refresh()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function schedule(){busy.value=true;try{await api('jobs',{due_at:Number(due.value),quantity:Number(quantity.value)},key);key=crypto.randomUUID();await refresh()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function loadAudit(){try{audit.value=await api('audit')}catch(e){error.value=(e as Error).message}}
onUnmounted(()=>{if(timer)clearInterval(timer)})
</script>
<template>
  <main>
    <header><div><p class="app-label">Logistics simulator</p><h1>Storage<span>.</span></h1></div><div v-if="status" class="identity"><span>{{status.identity.username}} / {{status.identity.role}}</span><button @click="logout">Sign out</button></div><span v-else class="app-label">Sample execution foundation</span></header>
    <p v-if="error" role="alert" class="error">{{error}}</p>
    <section v-if="!status" class="login"><div><h2>Sign in</h2><p>Use an identity configured for this storage deployment.</p><form @submit.prevent="login"><label>Username<input name="username" v-model="username" autocomplete="username" required></label><label>Password<input name="password" type="password" v-model="password" autocomplete="current-password" required></label><button class="primary" :disabled="busy">{{busy?'Signing in…':'Sign in'}}</button></form></div><aside><h2>Sample execution</h2><p>Schedule quantities in simulation seconds. This foundation records completed sample work and boundary inputs.</p><p>Clock controls require an operator identity.</p></aside></section>
    <template v-else>
      <section data-status class="overview"><div class="clock"><p class="app-label">Granted simulation time</p><div class="seconds">{{status.run.granted.toLocaleString()}}<span>s</span></div><p>{{status.simulation_time}}</p><p>{{status.run.scenario.time_zone}} · seed {{status.run.scenario.seed}}</p></div><div class="metrics"><div><span>Run state</span><strong>{{status.run.state}}</strong></div><div><span>Completed quantity</span><strong>{{status.effects}} item</strong></div><div><span>Clock mode</span><strong>{{status.run.mode}} / {{status.run.speed}}×</strong></div><div><span>Pending boundary outputs</span><strong>{{status.pending_boundary_outputs}}</strong></div></div></section>
      <p v-if="status.run.error" class="error">{{status.run.error}}</p>
      <section class="watermarks"><span>Committed <b>{{status.run.committed}} s</b></span><span>Granted <b>{{status.run.granted}} s</b></span><span>Requested <b>{{status.run.requested}} s</b></span><span>Handoff quantum <b>{{status.quantum}} s</b></span></section>
      <section class="work"><div><h2>Schedule sample work</h2><form v-if="canSchedule" class="schedule" @submit.prevent="schedule"><label>Due at (simulation seconds)<input name="due_at" v-model="due" @input="newKey" type="number" min="0" step="any" required></label><label>Quantity (item)<input name="quantity" v-model="quantity" @input="newKey" type="number" min="1" max="10000" step="1" required></label><button class="primary" :disabled="busy">Schedule</button></form><p v-else>Your identity has read access.</p><p class="muted">Schedule at least one quantum beyond requested time. Retrying a failed request retains its idempotency key.</p></div><aside><h2>Boundary providers</h2><dl><template v-for="(provider,boundary) in status.providers" :key="boundary"><dt>{{boundary}}</dt><dd>{{provider}}</dd></template></dl><h3>Processes</h3><p v-if="!status.heartbeats.length">No process heartbeat received.</p><p v-for="beat in status.heartbeats" :key="beat.role">{{beat.role}} <strong>{{beat.healthy?'healthy':'unavailable'}}</strong></p></aside></section>
      <section v-if="operator" data-control class="controls"><h2>Run controls</h2><div class="buttons"><button :disabled="busy" @click="command(status.run.state==='held'?'resume':'hold')">{{status.run.state==='held'?'Resume':'Hold'}}</button><label v-if="status.run.mode==='standalone'">Speed<select :value="status.run.speed" @change="command('speed',{speed:Number(($event.target as HTMLSelectElement).value)})"><option v-for="speed in [1,5,20,60]" :value="speed" :key="speed">{{speed}}×</option></select></label><button :disabled="busy" @click="command('finalize')">Finalize</button><button @click="loadAudit">Load audit</button></div><div v-if="status.run.mode==='standalone'" class="reset"><p>New run archives the current run. Type its ID to confirm.</p><code>{{status.run.id}}</code><label>Current run ID<input v-model="confirmation" autocomplete="off"></label><button :disabled="busy||confirmation!==status.run.id" @click="command('reset',{confirm_run_id:confirmation});confirmation=''">New run</button></div></section>
      <section class="ledger"><div class="section-heading"><h2>Sample work ledger</h2><span>{{status.jobs.length}} most recent jobs</span></div><div class="table-scroll"><table><thead><tr><th>Job</th><th>Due (s)</th><th>Quantity (item)</th><th>Status</th><th>Attempts</th></tr></thead><tbody><tr v-for="job in status.jobs" :key="job.id"><td><code>{{job.id}}</code></td><td>{{job.due_at}}</td><td>{{job.payload.quantity}}</td><td>{{job.status}}</td><td>{{job.attempts}}</td></tr><tr v-if="!status.jobs.length"><td colspan="5">No sample work scheduled for this run.</td></tr></tbody></table></div></section>
      <section v-if="audit.length"><h2>Command audit</h2><div class="table-scroll"><table><thead><tr><th>Actor</th><th>Action</th><th>Outcome</th><th>HTTP status</th></tr></thead><tbody><tr v-for="event in audit" :key="event.id"><td>{{event.actor}}</td><td>{{event.action}}</td><td>{{event.outcome}}</td><td>{{event.status_code}}</td></tr></tbody></table></div></section>
      <footer><span>Run {{status.run.id}}</span><span>Epoch {{status.run.epoch}}</span></footer>
    </template>
  </main>
</template>
